// ChessBuddy service worker (generated by vite.config.ts at build time).
// Precaches the whole app so the installed version works offline.
// Requests to other sites (Chess.com, Lichess) are never cached.
const CACHE = 'chessbuddy-__VERSION__';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('chessbuddy-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    // Network first so updates show up; offline (or a shared-game link) falls back to the cached app.
    event.respondWith(fetch(req).catch(() => caches.match('./', { cacheName: CACHE }).then((r) => r || caches.match('./index.html'))));
    return;
  }
  event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req)));
});
